local _, WFJ = ...
WFJ.Data.add("book", {
  ["ea2630357f94edfd"] = { "L'⟦Hand of Dagun=Artiglio di Dagun⟧\n\nAntichi testi affermano che gli artigli di Dagun secernono un veleno che non uccide la preda, ma la trasforma in qualcos'altro: un membro delle antiche razze. Il suo valore per noi è indiscusso.\n\nDagun vive nelle profondità del mare, ma viene regolarmente attirato in superficie da una tribù di murloc Pinnamota ad ⟦Dustwallow Marsh=Acquemorte⟧. I loro oracoli lo evocano con un'alga marina incantata. Se uccidi abbastanza oracoli troverai l'alga. Poi posala sull'altare dei murloc, e Dagun arriverà.", "." },
  ["ea4dbe72b19e08fa"] = { "Morgan Ladimore era un cavaliere grande e nobile che combatteva in difesa degli innocenti, dei poveri e degli afflitti. Per molti anni operò con dedizione nelle regioni più remote di Azeroth, portando sollievo a chi soffriva e giustizia rapida ai malfattori.\n\nNell'estate del suo diciottesimo anno sposò una giovane di nome Lys. Si amavano molto ed ebbero infine tre figli, un maschio e due femmine.\n\nMorgan aveva trentadue anni quando scoppiò la guerra a", "." },
  ["ea96ef50e8e42705"] = { "LORD VALTHALAK, continua...\n\nSpezzato l'amuleto in frammenti, fuggimmo dal fantasma di Valthalak, appena risorto, e dal suo esercito di assassini spettrali. E il baccano che avevamo fatto litigando per l'amuleto aveva svegliato parecchi dei difensori rimasti nei Bastioni!\n\nQuasi tutti riuscimmo a uscire da ⟦Blackrock=Roccianera⟧ e ci credemmo al sicuro. Ma, persino dall'aldilà, Valthalak ci mandava contro i suoi servitori ovunque ci nascondessimo. Dopo quella missione The Veiled Blade si sciolse presto, e da allora fummo prede davvero facili.\n\nCome ormai saprai, questo fa della dimora di lord Valthalak, quella che oggi è la sala della Bestia nei ⟦Blackrock Spire=Bastioni di Roccianera⟧, l'ultimo dei luoghi infestati.", "." },
  ["eaa7c08990effa2e"] = { "Arthas e il suo Flagello invasero Quel'Thalas e assediarono le difese ormai cedevoli degli elfi. Sylvanas Windrunner, generale dei ranger di Lunargenta, combatté con valore, ma alla fine Arthas sterminò l'esercito degli alti elfi e si aprì la strada fino al Pozzo Solare. Con un crudele gesto di supremazia, rianimò perfino il corpo sconfitto di Sylvanas come banshee, condannata a un'eterna non morte al servizio del conquistatore di Quel'Thalas.", "." },
  ["eaaa9493620afaf5"] = { "essi avrebbero avuto la vita eterna, e nulla avrebbero dovuto temere dalla Separazione che stava per giungere...", "." },
  ["eaf2026693a6e7d1"] = { "Nel mezzo di questo caos, un misterioso profeta solitario apparve per guidare le razze mortali. Questo profeta non era altri che Medivh, l'ultimo Guardiano, tornato miracolosamente dall'Oltre per redimersi dai peccati del passato. Medivh avvertì l'⟦Horde=Orda⟧ e l'⟦Alliance=Alleanza⟧ dei pericoli che le attendevano e le esortò a unirsi.", "." },
  ["eaf6410a59d6f845"] = { "Nelle leggende dei troll si narra che la prima volta che la ⟦Stone of the Tides=Pietra delle Maree⟧ giunse nell'Impero Gurubashi, la trovò un guerriero troll che vagava lungo la costa di Rovotorto. Si imbatté in una misteriosa pietra azzurra al cui interno fluttuavano e scorrevano filamenti bianco latte. Incuriosito, il guerriero la portò con sé e proseguì il suo viaggio.\n\nCon il passare delle settimane e dei mesi, il guerriero scoprì che la pietra gli aveva dato il controllo sull'acqua. Poteva evocare", "." },
})
